#mystères{position:relative;overflow:hidden}
    #mysteries .wrap{position:relative;z-index:3}
    .myst-filterbar{display:flex;flex-wrap:wrap;gap:20px 28px;align-items:flex-end;margin-bottom:14px}
    .myst-filter-group{display:flex;flex-direction:column;gap:9px;min-width:0}
    .myst-filter-label{font-family:"Space Mono",ui-monospace,monospace;font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:#d3a8c2}
    .myst-chip-row{affichage:flex;flex-wrap:wrap;gap:8px}
    .myst-chip{
      display:inline-flex;align-items:center;gap:8px;cursor:pointer;
      remplissage : 9px 15px ; rayon de bordure : 999px ;
      famille de polices : "Space Mono", ui-monospace, monospace ; taille de police : 11 px ;
      espacement des lettres : .14em ; transformation du texte : majuscules ; couleur : #f4e3d7 ;
      arrière-plan:rgba(20,7,44,.72);bordure:1px solide rgba(255,45,124,.3);
      transition : facilité de transformation de 0,15 s, facilité de boîte-ombre de 0,2 s, facilité de couleur de bordure de 0,2 s ;
    }
    .myst-chip:hover{transform:translateY(-1px);border-color:rgba(255,45,124,.65);box-shadow:0 0 20px rgba(255,45,124,.25)}
    .myst-chip.active{
      background:var(--vi-grad-sunset,linear-gradient(90deg,#ff2d7c,#ff8a3d 52%,#ffd166));
      couleur:var(--vi-ink,#33051c);border-color:transparent;font-weight:700;
      box-shadow:0 8px 22px -8px rgba(255,45,124,.65);
    }
    .myst-chip .myst-dot{largeur:8px;hauteur:8px;border-radius:99px;flex:0 0 auto}
    .myst-chip.active .myst-dot{contour:1px solid rgba(51,5,28,.4)}
    .myst-dot--résolu{background:linear-gradient(135deg,var(--vi-gold,#ffd166),#7ee08c)}
    .myst-dot--open{background:var(--vi-pink,#ff2d7c);box-shadow:0 0 10px rgba(255,45,124,.8)}
    .myst-dot--lenda{background:var(--vi-purple,#7b2ff7);box-shadow:0 0 10px rgba(123,47,247,.8)}
    .myst-dot--all{background:#f4e3d7}
    .myst-chip petit{
      taille de police : 10 px ; remplissage : 2 px 7 px ; rayon de bordure : 99 px ; espacement des lettres : 0,08 em ;
      arrière-plan:rgba(11,13,42,.55);couleur:hériter;bordure:1px solide rgba(255,255,255,.18);
    }
    .myst-chip.active small{background:rgba(51,5,28,.22);border-color:rgba(51,5,28,.3)}
    .myst-select{
      apparence : aucune ;-webkit-apparence : aucune ; curseur : pointeur ; largeur min : 220 px ;
      remplissage : 10px 38px 10px 14px ; rayon de bordure : 10px ;
      famille de polices : "Space Mono", ui-monospace, monospace ; taille de police : 12 px ; espacement des lettres : 0,06 em ;
      couleur : #fff5ec ; arrière-plan : rgba (20,7,44,.72) ; bordure : 1px solide rgba (255,45,124,.3) ;
      background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='12' height='8' viewBox='0 0 12 8'><path d='M1 1l5 5 5-5' fill='none' Stroke='%23ff2d7c' Stroke-width='2' Stroke-linecap='round'/></svg>");
      répétition d'arrière-plan : pas de répétition ; position d'arrière-plan : centre droit de 14 px ;
    }
    .myst-select:focus{outline:none;border-color:rgba(255,45,124,.7);box-shadow:0 0 18px rgba(255,45,124,.3)}
    Option .myst-select{fond :#0b0d2a;couleur :#fff5ec}
    .myst-status-desc{
      marge:0 0 18px;largeur maximale:760px;couleur:#d9c3d2;taille de police:14px;hauteur de ligne:1,6;
      bordure gauche : 3 px, rgba solide (255,45, 124, .55) ; rembourrage gauche : 14 px ;
    }
    .myst-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:18px;align-items:start}
    .myst-card{display:flex;flex-direction:column;gap:0;padding:22px 22px 18px}
    .myst-card-top{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:14px}
    .myst-file-no{font-family:"Space Mono",ui-monospace,monospace;font-size:10px;letter-spacing:.22em;color:#b98ca9;text-transform:majuscule}
    .myst-stamp{transform:rotate(-2deg);font-size:10px;letter-spacing:.2em;padding:6px 13px}
    .myst-stamp--résolu{
      background:linear-gradient(90deg,var(--vi-gold,#ffd166),#7ee08c);
      couleur:var(--vi-ink,#33051c);box-shadow:0 8px 22px -8px rgba(255 209 102,.7),0 0 20px rgba(126 224 140,.25);
    }
    .myst-stamp--open{color:var(--vi-pink,#ff2d7c);box-shadow:0 0 22px rgba(255,45,124,.4)}
    .myst-stamp--légende{
      couleur:#cfa9ff;box-shadow:0 0 22px rgba(123,47,247,.45);
      contexte :
        dégradé linéaire (rgba (26,9,54,.9), rgba (26,9,54,.9)) boîte de remplissage,
        gradient-linéaire(90deg,var(--vi-purple,#7b2ff7),var(--vi-pink-2,#f152ff)) border-box;
    }
    .myst-jeu-chip{
      display:inline-flex;align-items:center;gap:6px;margin-bottom:10px;
      font-family:"Space Mono",ui-monospace,monospace;font-size:10px;
      espacement des lettres: .18em; transformation du texte: majuscules; couleur: var (--vi-gold, #ffd166);
    }
    .myst-game-chip::before{content:"";width:14px;height:1px;background:var(--vi-gold,#ffd166);opacity:.7}
    .myst-card h3{marge :0 0 10px;font-size:20px;line-height:1.25;color:#fff5ec}
    .myst-desc{margin:0;color:#d9c8d4;font-size:14px;line-height:1.62}
    .myst-toggle{margin-top:16px;align-self:flex-start}
    .myst-body{margin-top:16px;padding-top:16px;border-top:1px pointillé rgba(255,45,124,.35)}
    .myst-evidence-label{
      display:flex;align-items:center;gap:8px;margin:16px 0 4px;
      font-family:"Space Mono",ui-monospace,monospace;font-size:10px;
      espacement des lettres : .26em ; transformation du texte : majuscules ; couleur : #ff9ec4 ;
    }
    .myst-evidence-label:premier-enfant{margin-top:0}
    .myst-evidence-label::after{content:"";flex:1;height:1px;background:rgba(255,45,124,.25)}
    .myst-list{list-style:none;margin:8px 0 0;padding:0}
    .myst-list li{display:flex;gap:10px;align-items:baseline;margin-bottom:8px;color:#e6d6dd;font-size:13.5px;line-height:1.6}
    .myst-idx{
      flex:0 0 auto;font-family:"Space Mono",ui-monospace,monospace;font-size:10px;
      espacement des lettres : .08em; couleur: var (--vi-gold, #ffd166); opacité: .85; largeur min: 30 px;
    }
    .myst-résolution{
      marge supérieure : 18 px ; remplissage : 14px 16px ; rayon-bordure : 10px ;
      bordure : 1px en pointillés rgba(255 209 102,.6);arrière-plan :rgba(255 209 102,.07);
    }
    .myst-resolution .myst-evidence-label{color:var(--vi-gold,#ffd166);margin-top:0}
    .myst-resolution .myst-evidence-label::after{background:rgba(255,209,102,.35)}
    .myst-resolution p{margin:8px 0 0;color:#ffe9bd;font-size:13.5px;line-height:1.62}
    .myst-où{
      display:flex;gap:10px;align-items:baseline;margin-top:16px;
      famille de polices : "Space Mono", ui-monospace, monospace ; taille de police : 12 px ;
      couleur : #cdb4c6 ; hauteur de ligne : 1,55 ;
    }
    .myst-where svg{flex:0 0 auto;width:14px;height:14px;transform:translateY(2px);color:var(--vi-pink,#ff2d7c)}
    .myst-vide{
      remplissage : 34 px 26 px ; alignement du texte : centre ; couleur : #d3a8c2 ;
      famille de polices : "Space Mono", ui-monospace, monospace ; taille de police : 13 px ; espacement des lettres : 0,08 em ;
    }
    @media (largeur maximale : 760 px) {
      .myst-filterbar{flex-direction:colonne;align-items:stretch}
      .myst-select{largeur:100%}
      .myst-grid{grid-template-columns:1fr}
      .myst-card{padding:18px 16px 16px}
    }
    @media (préfère-reduced-motion:reduce){
      .myst-chip,.myst-chip:hover{transform:none;transition:none}
    }
